    /**
     * Each icon's key and English name, in the picker's order: the admin's
     * choice of icon.
     *
     * @return array<string, string>
     */
    public static function labels(): array
    {
        return self::LABELS;
    }

    /**
     * Every icon's key, in the picker's order.
     *
     * @return list<string>
     */
    public static function keys(): array
    {
        return array_keys(self::PATHS);
    }

    /** The icon as inline SVG in the text's colour, or null for no (or an unknown) icon. */
    public static function svg(?string $key): ?string
    {
        $paths = self::PATHS[$key ?? ''] ?? null;

        return $paths === null ? null
            : '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'.$paths.'</svg>';
    }
